"use client";

import { useState } from "react";
import { createPortal } from "react-dom";
import { Badge } from "@/components/ui/primitives";

export type EmailLogRow = {
  id: string;
  toEmail: string;
  subject: string;
  template: string | null;
  status: string;
  error: string | null;
  html: string;
  createdAt: string; // ISO
  openedAt: string | null;
  openCount: number;
  clickedAt: string | null;
  clickCount: number;
};

function fmt(iso: string): string {
  return iso.replace("T", " ").slice(0, 19);
}

function pct(n: number, d: number): string {
  if (d <= 0) return "0%";
  return `${Math.round((n / d) * 100)}%`;
}

/**
 * Previewing a stored email must never itself count as the recipient opening
 * it — the stored `html` carries a live tracking pixel pointed at
 * /api/track/email/[id]/open, and an admin's browser will fetch it exactly
 * like a real mail client would the instant the iframe renders. Strip that
 * one `<img>` before handing the HTML to the iframe. Click links are left
 * alone: `sandbox=""` below already blocks all navigation from inside the
 * preview, so they're inert without needing to be rewritten too.
 */
function stripTrackingPixel(html: string): string {
  return html.replace(/<img[^>]*\/api\/track\/email\/[^>]*>/gi, "");
}

/**
 * Admin viewer for sent/failed emails. A table of recent messages with a
 * per-row "Preview" that renders the stored HTML inside a sandboxed iframe,
 * plus open/click engagement (lib/mailer.ts rewrites every sent HTML body
 * with a tracking pixel and per-link redirects — see injectEmailTracking).
 */
export function EmailLogViewer({ logs }: { logs: EmailLogRow[] }) {
  const [preview, setPreview] = useState<EmailLogRow | null>(null);

  if (!logs.length) {
    return (
      <div className="card p-6 text-sm text-slate-400">
        No emails have been sent yet. They&apos;ll appear here the moment Nxeon dispatches one.
      </div>
    );
  }

  const sent = logs.filter((l) => l.status === "SENT");
  const opened = sent.filter((l) => l.openedAt).length;
  const clicked = sent.filter((l) => l.clickedAt).length;

  return (
    <>
      <div className="grid grid-cols-3 gap-4">
        <div className="card">
          <p className="text-xs text-slate-500">Sent (shown below)</p>
          <p className="mt-1 text-2xl font-semibold tabular-nums">{sent.length}</p>
        </div>
        <div className="card">
          <p className="text-xs text-slate-500">Open rate</p>
          <p className="mt-1 text-2xl font-semibold tabular-nums">{pct(opened, sent.length)}</p>
          <p className="mt-0.5 text-xs text-slate-500">{opened} of {sent.length} opened</p>
        </div>
        <div className="card">
          <p className="text-xs text-slate-500">Click rate</p>
          <p className="mt-1 text-2xl font-semibold tabular-nums">{pct(clicked, sent.length)}</p>
          <p className="mt-0.5 text-xs text-slate-500">{clicked} of {sent.length} clicked a link</p>
        </div>
      </div>

      <div className="card overflow-x-auto p-0">
        <table className="table-shell">
          <thead>
            <tr>
              <th>Time</th>
              <th>To</th>
              <th>Subject</th>
              <th>Template</th>
              <th>Status</th>
              <th>Opened</th>
              <th>Clicked</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {logs.map((l) => (
              <tr key={l.id}>
                <td className="whitespace-nowrap text-slate-400">{fmt(l.createdAt)}</td>
                <td className="whitespace-nowrap">{l.toEmail}</td>
                <td className="max-w-xs truncate">{l.subject}</td>
                <td>
                  {l.template ? (
                    <code className="font-mono text-xs text-brand-300">{l.template}</code>
                  ) : (
                    <span className="text-slate-600">—</span>
                  )}
                </td>
                <td>
                  {l.status === "SENT" ? (
                    <Badge tone="green">sent</Badge>
                  ) : (
                    <Badge tone="red">failed</Badge>
                  )}
                  {l.error && <span className="ml-2 text-xs text-red-400/80" title={l.error}>{l.error.slice(0, 40)}</span>}
                </td>
                <td className="whitespace-nowrap" title={l.openedAt ? fmt(l.openedAt) : undefined}>
                  {l.openedAt ? (
                    <Badge tone="brand">opened{l.openCount > 1 ? ` ×${l.openCount}` : ""}</Badge>
                  ) : (
                    <span className="text-slate-600">—</span>
                  )}
                </td>
                <td className="whitespace-nowrap" title={l.clickedAt ? fmt(l.clickedAt) : undefined}>
                  {l.clickedAt ? (
                    <Badge tone="amber">clicked{l.clickCount > 1 ? ` ×${l.clickCount}` : ""}</Badge>
                  ) : (
                    <span className="text-slate-600">—</span>
                  )}
                </td>
                <td className="text-right">
                  <button onClick={() => setPreview(l)} className="btn-ghost text-xs">
                    Preview
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Rendered into document.body so the fixed overlay is anchored to the
          viewport — an ancestor with a CSS transform would otherwise make
          `position: fixed` relative to IT, dropping the modal far down the page. */}
      {preview &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4"
            onClick={() => setPreview(null)}
          >
          <div
            className="card flex h-[85vh] w-full max-w-2xl flex-col overflow-hidden p-0"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-start justify-between gap-4 border-b border-white/[0.06] px-5 py-3">
              <div className="min-w-0">
                <p className="truncate text-sm font-semibold text-white">{preview.subject}</p>
                <p className="mt-0.5 truncate text-xs text-slate-500">
                  To {preview.toEmail} · {fmt(preview.createdAt)}
                  {preview.template ? ` · ${preview.template}` : ""}
                </p>
              </div>
              <button onClick={() => setPreview(null)} className="btn-ghost text-xs">
                Close
              </button>
            </div>
            {preview.error && (
              <div className="border-b border-red-500/20 bg-red-500/10 px-5 py-2 text-xs text-red-300">
                {preview.error}
              </div>
            )}
            <iframe
              title="Email preview"
              srcDoc={stripTrackingPixel(preview.html)}
              sandbox=""
              className="w-full flex-1 border-0 bg-white"
            />
          </div>
          </div>,
          document.body,
        )}
    </>
  );
}

export default EmailLogViewer;

import Link from "next/link";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { EmailLogViewer, type EmailLogRow } from "@/components/admin/EmailLogViewer";
import { ErrorLogViewer } from "@/components/admin/ErrorLogViewer";
import { listErrors } from "@/lib/actions-errors";
import { actingAdminId, detailWithoutActor } from "@/lib/admin-metrics";

/**
 * Resolve the real admin behind any audit row taken while impersonating.
 * See the docblock on `actingAdminId` — `userId` stays the customer by design, so
 * every reader of the audit table has to do this or it credits the wrong person.
 */
async function actorEmails(logs: { detail: string | null }[]): Promise<Map<string, string>> {
  const ids = [...new Set(logs.map((l) => actingAdminId(l.detail)).filter(Boolean))] as string[];
  if (ids.length === 0) return new Map();
  const users = await db.user.findMany({ where: { id: { in: ids } }, select: { id: true, email: true } });
  return new Map(users.map((u) => [u.id, u.email]));
}

export const dynamic = "force-dynamic";

type Tab = "audit" | "activity" | "email" | "errors";
const TABS: { key: Tab; label: string }[] = [
  { key: "audit", label: "Audit" },
  { key: "activity", label: "Activity" },
  { key: "email", label: "Email" },
  { key: "errors", label: "Errors" },
];

export default async function AdminLogs({
  searchParams,
}: {
  searchParams: Promise<{ tab?: string }>;
}) {
  await requireArea("platform");
  const sp = await searchParams;
  const tab: Tab = (["audit", "activity", "email", "errors"] as const).includes(sp.tab as Tab)
    ? (sp.tab as Tab)
    : "audit";

  return (
    <div className="space-y-6">
      <PageHeader title="Logs" sub="Audit trail, platform activity, and outbound email">
        <Badge tone="slate">platform</Badge>
      </PageHeader>

      {/* Tabs */}
      <div className="flex gap-1 rounded-xl border border-white/[0.06] bg-white/[0.02] p-1">
        {TABS.map((t) => (
          <Link
            key={t.key}
            href={`/admin/logs?tab=${t.key}`}
            className={`rounded-lg px-4 py-1.5 text-sm font-medium transition-colors ${
              tab === t.key ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white" : "text-slate-400 hover:text-white"
            }`}
          >
            {t.label}
          </Link>
        ))}
      </div>

      {tab === "audit" && <AuditTab />}
      {tab === "activity" && <ActivityTab />}
      {tab === "email" && <EmailTab />}
      {tab === "errors" && <ErrorsTab />}
    </div>
  );
}

/* ---------------- Errors ---------------- */

async function ErrorsTab() {
  // Default view: unresolved errors, newest activity first. Interactive
  // filtering / resolving happens client-side via the admin-gated actions.
  const { rows } = await listErrors({ resolved: false, pageSize: 200 });
  return <ErrorLogViewer initial={rows} />;
}

/* ---------------- Audit ---------------- */

async function AuditTab() {
  const logs = await db.auditLog.findMany({
    include: { user: { select: { email: true, id: true } } },
    orderBy: { createdAt: "desc" },
    take: 200,
  });
  const actors = await actorEmails(logs);

  return (
    <div className="card overflow-x-auto p-0">
      <table className="table-shell">
        <thead>
          <tr>
            <th>Time</th>
            <th>Actor</th>
            <th>Action</th>
            <th>Detail</th>
          </tr>
        </thead>
        <tbody>
          {logs.map((l) => {
            const asAdmin = actingAdminId(l.detail);
            const detail = asAdmin ? detailWithoutActor(l.detail) : (l.detail ?? "");
            return (
              <tr key={l.id}>
                <td className="whitespace-nowrap text-slate-400">
                  {l.createdAt.toISOString().replace("T", " ").slice(0, 19)}
                </td>
                <td>
                  {asAdmin ? (
                    <div className="flex flex-wrap items-center gap-2">
                      <Link href={`/admin/users/${asAdmin}`} className="hover:text-brand-300">
                        {actors.get(asAdmin) ?? asAdmin}
                      </Link>
                      <Badge tone="amber">impersonating {l.user?.email ?? "customer"}</Badge>
                    </div>
                  ) : l.user ? (
                    <Link href={`/admin/users/${l.user.id}`} className="hover:text-brand-300">
                      {l.user.email}
                    </Link>
                  ) : (
                    <span className="text-slate-500">system</span>
                  )}
                </td>
                <td className="font-mono text-xs">{l.action}</td>
                <td className="max-w-md truncate text-slate-400" title={detail}>
                  {detail}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

/* ---------------- Activity feed ---------------- */

type Activity = {
  id: string;
  at: Date;
  kind: "audit" | "payment" | "job";
  tone: "brand" | "green" | "amber" | "slate" | "red";
  label: string;
  text: string;
  actor?: string | null;
};

async function ActivityTab() {
  const [audits, txns, jobs] = await Promise.all([
    db.auditLog.findMany({
      include: { user: { select: { email: true } } },
      orderBy: { createdAt: "desc" },
      take: 40,
    }),
    db.walletTransaction.findMany({
      include: { user: { select: { email: true } } },
      orderBy: { createdAt: "desc" },
      take: 40,
    }),
    db.job.findMany({ orderBy: { createdAt: "desc" }, take: 40 }),
  ]);

  const items: Activity[] = [];
  const actors = await actorEmails(audits);

  for (const a of audits) {
    // Same attribution rule as the Audit tab: an action taken while impersonating
    // belongs to the admin who took it, not to the account it was taken as.
    const asAdmin = actingAdminId(a.detail);
    items.push({
      id: `a-${a.id}`,
      at: a.createdAt,
      kind: "audit",
      tone: asAdmin || a.action.startsWith("admin.") ? "amber" : "brand",
      label: a.action,
      text: asAdmin ? detailWithoutActor(a.detail) : (a.detail ?? ""),
      actor: asAdmin
        ? `${actors.get(asAdmin) ?? asAdmin} — impersonating ${a.user?.email ?? "customer"}`
        : (a.user?.email ?? "system"),
    });
  }
  for (const t of txns) {
    const credit = t.amountCents >= 0;
    items.push({
      id: `t-${t.id}`,
      at: t.createdAt,
      kind: "payment",
      tone: credit ? "green" : "slate",
      label: credit ? "wallet.credit" : "wallet.debit",
      text: `${fmtMoney(t.amountCents)} · ${t.description}`,
      actor: t.user?.email ?? null,
    });
  }
  for (const j of jobs) {
    items.push({
      id: `j-${j.id}`,
      at: j.createdAt,
      kind: "job",
      tone: j.status === "FAILED" ? "red" : j.status === "DONE" ? "green" : "slate",
      label: `job.${String(j.type).toLowerCase()}`,
      text: `${j.status}${j.error ? ` · ${j.error}` : ""}`,
      actor: null,
    });
  }

  items.sort((a, b) => b.at.getTime() - a.at.getTime());
  const feed = items.slice(0, 80);

  return (
    <div className="card divide-y divide-white/[0.05] p-0">
      {feed.map((it) => (
        <div key={it.id} className="flex items-start gap-3 px-4 py-3">
          <Badge tone={it.tone}>{it.kind}</Badge>
          <div className="min-w-0 flex-1">
            <p className="text-sm">
              <code className="font-mono text-xs text-brand-300">{it.label}</code>
              {it.text && <span className="ml-2 text-slate-300">{it.text}</span>}
            </p>
            {it.actor && <p className="mt-0.5 text-xs text-slate-500">{it.actor}</p>}
          </div>
          <span className="whitespace-nowrap text-xs text-slate-500" title={it.at.toISOString()}>
            {timeAgo(it.at)}
          </span>
        </div>
      ))}
    </div>
  );
}

/* ---------------- Email ---------------- */

async function EmailTab() {
  const rows = await db.emailLog.findMany({ orderBy: { createdAt: "desc" }, take: 200 });
  const logs: EmailLogRow[] = rows.map((r) => ({
    id: r.id,
    toEmail: r.toEmail,
    subject: r.subject,
    template: r.template,
    status: r.status,
    error: r.error,
    html: r.html,
    createdAt: r.createdAt.toISOString(),
    openedAt: r.openedAt ? r.openedAt.toISOString() : null,
    openCount: r.openCount,
    clickedAt: r.clickedAt ? r.clickedAt.toISOString() : null,
    clickCount: r.clickCount,
  }));
  return <EmailLogViewer logs={logs} />;
}

// Cold Email Engine — sending transport + message rendering (Phase 2).
//
// This module has TWO halves:
//
//   1. PURE rendering (`renderStepBody`, `buildMessage`, `injectTracking`,
//      markdown → HTML). No I/O, no DB, no network — the send worker AND the test
//      suite call these identically. Importing this module never opens a socket.
//
//   2. A pluggable `MailTransport` interface with a Nxeon Mail SMTP adapter
//      (reusing the platform's SMTP Setting mechanism from lib/mailer.ts) and an
//      SES adapter SEAM for later. Only `NxeonSmtpTransport.send()` touches the
//      network, and it is only ever reached from the send worker, which is hard-
//      gated behind the `cold_email_sending_enabled` kill-switch.
//
// SAFETY: nothing here checks the kill-switch or the suppression list itself —
// those gates live in the worker so they are enforced once, at the choke point,
// immediately before each send. This module assumes the caller has already
// cleared a message to send.

import nodemailer from "nodemailer";
import { appUrl } from "@/lib/email-render";
import {
  complianceFooter,
  unsubscribeToken,
  openTrackingToken,
  clickTrackingToken,
  normalizeDomain,
  type BrandLike,
} from "@/lib/coldemail/compliance";

// ---------------------------------------------------------------------------
// Shapes
// ---------------------------------------------------------------------------

export type SendIdentity = BrandLike & {
  id: string;
  name?: string | null;
  fromName?: string | null;
  fromEmail?: string | null;
  replyTo?: string | null;
  sendingDomain?: string | null;
};

export type StepLike = { subject: string; bodyMarkdown: string };

export type ContactLike = {
  id: string;
  email: string;
  fullName?: string | null;
  title?: string | null;
  business?: { name?: string | null } | null;
};

export type RenderedMessage = {
  from: string;
  to: string;
  replyTo?: string;
  subject: string;
  html: string;
  text: string;
  headers: Record<string, string>;
};

export type SendResult = { messageId?: string };

/** A transport is anything that can put one fully-rendered message on the wire. */
export interface MailTransport {
  readonly name: string;
  send(msg: RenderedMessage): Promise<SendResult>;
}

// ---------------------------------------------------------------------------
// Minimal, dependency-free markdown → HTML (no `marked` in this repo).
// Supports: paragraphs, line breaks, **bold**, *italic*, [text](url), and bare
// autolinks. Everything is escaped first, so raw HTML in the body is inert.
// ---------------------------------------------------------------------------

function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

/** Render a markdown body to safe inline-styled HTML paragraphs. */
export function markdownToHtml(md: string): string {
  const inline = (raw: string): string => {
    let s = esc(raw);
    // [label](http…) links — label and URL are already escaped.
    s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (_m, label, url) => {
      return `<a href="${url}" style="color:#6f47f5;text-decoration:underline;">${label}</a>`;
    });
    // Bare autolinks not already inside an <a href="…">.
    s = s.replace(/(^|[\s(])((https?:\/\/[^\s<)]+))/g, (_m, pre, url) => {
      return `${pre}<a href="${url}" style="color:#6f47f5;text-decoration:underline;">${url}</a>`;
    });
    s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    s = s.replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>");
    return s;
  };

  const paragraphs = String(md ?? "")
    .replace(/\r\n?/g, "\n")
    .split(/\n{2,}/)
    .map((p) => p.trim())
    .filter(Boolean)
    .map((p) => {
      const body = p.split("\n").map(inline).join("<br/>");
      return `<p style="margin:0 0 16px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#4a4763;">${body}</p>`;
    });
  return paragraphs.join("\n");
}

// ---------------------------------------------------------------------------
// Variable substitution for personalization tokens ({{firstName}}, {{company}}…)
// ---------------------------------------------------------------------------

export function contactVars(contact: ContactLike): Record<string, string> {
  const full = (contact.fullName ?? "").trim();
  const firstName = full.split(/\s+/)[0] ?? "";
  return {
    firstName,
    fullName: full,
    title: (contact.title ?? "").trim(),
    email: contact.email,
    company: (contact.business?.name ?? "").trim(),
  };
}

function substitute(input: string, vars: Record<string, string>): string {
  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key: string) =>
    vars[key] !== undefined ? vars[key] : "",
  );
}

// ---------------------------------------------------------------------------
// Tracking injection (open pixel + click-through rewriting). PURE.
// ---------------------------------------------------------------------------

export function openPixelUrl(base: string, sendId: string): string {
  return `${base.replace(/\/$/, "")}/api/coldemail/track/open/${openTrackingToken(sendId)}`;
}

export function clickWrapUrl(base: string, sendId: string, target: string): string {
  return `${base.replace(/\/$/, "")}/api/coldemail/track/click/${clickTrackingToken(sendId, target)}`;
}

/**
 * Rewrite outbound `<a href="http…">` links through the click-tracking redirect
 * and append a 1x1 open pixel. Applied ONLY at send time — previews never call
 * this, so an operator's preview shows real, unwrapped links. The unsubscribe
 * link is deliberately left un-wrapped: it must remain a direct, one-click,
 * no-JS, no-redirect target per RFC 8058.
 */
export function injectTracking(html: string, sendId: string, base: string, opts: { skip?: (url: string) => boolean } = {}): string {
  const skip = opts.skip ?? (() => false);
  const rewritten = html.replace(/href="(https?:\/\/[^"]+)"/gi, (m, url: string) => {
    if (skip(url)) return m;
    return `href="${clickWrapUrl(base, sendId, url)}"`;
  });
  const pixel = `<img src="${openPixelUrl(base, sendId)}" width="1" height="1" alt="" style="display:none;width:1px;height:1px;border:0;" />`;
  return `${rewritten}\n${pixel}`;
}

// ---------------------------------------------------------------------------
// Message rendering (PURE — the heart the tests exercise)
// ---------------------------------------------------------------------------

/** Build the `From` header value from a brand identity. */
export function fromHeader(identity: SendIdentity): string {
  const email = (identity.fromEmail ?? "").trim();
  const name = (identity.fromName ?? identity.name ?? "").trim();
  return name ? `${name} <${email}>` : email;
}

/** The From domain used for reputation-isolation checks. */
export function identityDomain(identity: SendIdentity): string {
  return normalizeDomain(identity.sendingDomain) || normalizeDomain(identity.fromEmail);
}

export type BuildMessageOpts = {
  identity: SendIdentity;
  step: StepLike;
  contact: ContactLike;
  /** ColdSend id — anchors tracking tokens. Omit for a plain preview. */
  sendId?: string;
  /** Base URL for links (defaults to appUrl()). */
  base?: string;
  /** Extra disclosure line appended under the required footer. */
  footerDisclosure?: string;
  /** Inject open pixel + click tracking. FALSE for previews. */
  track?: boolean;
};

/**
 * Render one SequenceStep into a fully-formed, compliant message:
 *  - subject + markdown body with {{tokens}} substituted,
 *  - the mandatory compliance footer (postal address + one-click unsubscribe),
 *  - `List-Unsubscribe` + `List-Unsubscribe-Post` headers (RFC 8058),
 *  - open/click tracking when `track` and a `sendId` are supplied.
 *
 * No network, no DB — deterministic given its inputs.
 */
/**
 * Minimal HTML shell for a cold-email send — deliberately NOT `wrapEmail()`
 * (the transactional shell used for invoices/password-resets/etc). That shell
 * hardcodes its own footer with a fixed company address and "you're receiving
 * this because you have a Nxeon account" — both wrong here: `buildMessage`
 * already renders the correct, per-brand compliance footer (real postal
 * address + real unsubscribe) right in `contentHtml`, so wrapping it in a
 * second template just duplicated that footer with WRONG information
 * underneath the right one. Confirmed live: a rendered preview showed two
 * different postal addresses in the same email and a false account-holder
 * claim to a cold-outreach recipient who has never signed up for anything.
 *
 * Also deliberately plain rather than branded: no gradient header, no logo
 * image, no Dashboard/Help/Support nav — a heavy marketing-template look is
 * exactly what current cold-email deliverability guidance says to avoid; a
 * cold email should read like a real person's message, not a mass send.
 */
function wrapColdEmailHtml(contentHtml: string, preheader: string): string {
  const hidden = `<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:#ffffff;opacity:0;">${esc(preheader)}</div>`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="color-scheme" content="light"/><title></title></head>
