"use client";

import { useState } from "react";
import { createPortal } from "react-dom";
import { useRouter } from "next/navigation";
import { Badge } from "@/components/ui/primitives";

export type SentEmailRow = {
  id: string;
  toEmail: string;
  campaignName: string;
  /** Rendered subject as actually sent. Null for legacy sends predating this feature. */
  subject: string | null;
  status: string;
  error: string | null;
  /** Rendered HTML as actually sent (post-personalization, post-tracking-injection). */
  html: string | null;
  sentAt: string; // ISO
  openedAt: string | null;
  openCount: number;
  clickedAt: string | null;
  clickCount: number;
};

function fmt(iso: string): string {
  return iso.replace("T", " ").slice(0, 19);
}

function pct(n: number, d: number): string {
  if (d <= 0) return "0%";
  return `${Math.round((n / d) * 100)}%`;
}

/**
 * Previewing a stored cold-email send must never itself count as the recipient
 * opening it — `bodyHtmlSent` carries a live tracking pixel pointed at
 * /api/coldemail/track/open/[token] (see openPixelUrl in lib/coldemail/sender.ts),
 * and an admin's browser would fetch it exactly like a real mail client the
 * instant the iframe renders. Strip that one `<img>` before handing the HTML to
 * the iframe. This mirrors stripTrackingPixel() in components/admin/EmailLogViewer.tsx
 * exactly in behavior, just re-targeted at cold email's own pixel path (the
 * transactional mailer's tracking lives at /api/track/email/... instead). Click
 * links are left alone: `sandbox=""` below already blocks all navigation from
 * inside the preview, so they're inert without needing to be rewritten too.
 */
function stripTrackingPixel(html: string): string {
  return html.replace(/<img[^>]*\/api\/coldemail\/track\/open\/[^>]*>/gi, "");
}

/**
 * Admin viewer for sent cold-email messages — a structural copy of
 * EmailLogViewer.tsx's table + modal + sandboxed-iframe pattern, adapted to
 * ColdSend's shape (subjectSent/bodyHtmlSent captured at send time in
 * worker/coldemail.ts, joined here to the contact's email).
 *
 * Sends made before subjectSent/bodyHtmlSent existed have no stored content —
 * `subject`/`html` are null for those rows — and are shown with the Preview
 * button replaced by an explanatory note rather than hidden entirely, so the
 * table stays an honest record of everything that was sent.
 */
export function SentEmailViewer({
  rows,
  campaigns,
  selectedCampaignId,
  showCampaignColumn,
}: {
  rows: SentEmailRow[];
  campaigns: { id: string; name: string }[];
  selectedCampaignId: string;
  showCampaignColumn: boolean;
}) {
  const [preview, setPreview] = useState<SentEmailRow | null>(null);
  const router = useRouter();

  const previewable = rows.filter((r) => r.html);
  const opened = rows.filter((r) => r.openedAt).length;
  const clicked = rows.filter((r) => r.clickedAt).length;

  return (
    <>
      <div className="flex flex-wrap items-center justify-end gap-2">
        <label className="text-xs text-slate-500" htmlFor="campaign-filter">
          Campaign
        </label>
        <select
          id="campaign-filter"
          className="input w-auto py-1.5 text-sm"
          value={selectedCampaignId}
          onChange={(e) => {
            const id = e.target.value;
            router.push(id ? `/admin/coldemail/sent?campaignId=${id}` : "/admin/coldemail/sent");
          }}
        >
          <option value="">All campaigns</option>
          {campaigns.map((c) => (
            <option key={c.id} value={c.id}>
              {c.name}
            </option>
          ))}
        </select>
      </div>

      {!rows.length ? (
        <div className="card p-6 text-sm text-slate-400">
          No cold emails have been sent yet{selectedCampaignId ? " for this campaign" : ""}. They&apos;ll appear here
          the moment a campaign dispatches one.
        </div>
      ) : (
        <>
          <div className="grid grid-cols-3 gap-4">
            <div className="card">
              <p className="text-xs text-slate-500">Sent (shown below)</p>
              <p className="mt-1 text-2xl font-semibold tabular-nums">{rows.length}</p>
              <p className="mt-0.5 text-xs text-slate-500">{previewable.length} with a preview available</p>
            </div>
            <div className="card">
              <p className="text-xs text-slate-500">Open rate</p>
              <p className="mt-1 text-2xl font-semibold tabular-nums">{pct(opened, rows.length)}</p>
              <p className="mt-0.5 text-xs text-slate-500">{opened} of {rows.length} opened</p>
            </div>
            <div className="card">
              <p className="text-xs text-slate-500">Click rate</p>
              <p className="mt-1 text-2xl font-semibold tabular-nums">{pct(clicked, rows.length)}</p>
              <p className="mt-0.5 text-xs text-slate-500">{clicked} of {rows.length} clicked a link</p>
            </div>
          </div>

          <div className="card overflow-x-auto p-0">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Time</th>
                  <th>To</th>
                  <th>Subject</th>
                  {showCampaignColumn && <th>Campaign</th>}
                  <th>Status</th>
                  <th>Opened</th>
                  <th>Clicked</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {rows.map((r) => (
                  <tr key={r.id}>
                    <td className="whitespace-nowrap text-slate-400">{fmt(r.sentAt)}</td>
                    <td className="whitespace-nowrap">{r.toEmail}</td>
                    <td className="max-w-xs truncate">
                      {r.subject ?? <span className="text-slate-600">—</span>}
                    </td>
                    {showCampaignColumn && (
                      <td className="whitespace-nowrap text-slate-400">{r.campaignName}</td>
                    )}
                    <td>
                      {r.status === "SENT" ? (
                        <Badge tone="green">sent</Badge>
                      ) : (
                        <Badge tone="red">{r.status.toLowerCase()}</Badge>
                      )}
                      {r.error && <span className="ml-2 text-xs text-red-400/80" title={r.error}>{r.error.slice(0, 40)}</span>}
                    </td>
                    <td className="whitespace-nowrap" title={r.openedAt ? fmt(r.openedAt) : undefined}>
                      {r.openedAt ? (
                        <Badge tone="brand">opened{r.openCount > 1 ? ` ×${r.openCount}` : ""}</Badge>
                      ) : (
                        <span className="text-slate-600">—</span>
                      )}
                    </td>
                    <td className="whitespace-nowrap" title={r.clickedAt ? fmt(r.clickedAt) : undefined}>
                      {r.clickedAt ? (
                        <Badge tone="amber">clicked{r.clickCount > 1 ? ` ×${r.clickCount}` : ""}</Badge>
                      ) : (
                        <span className="text-slate-600">—</span>
                      )}
                    </td>
                    <td className="text-right">
                      {r.html ? (
                        <button onClick={() => setPreview(r)} className="btn-ghost text-xs">
                          Preview
                        </button>
                      ) : (
                        <span className="text-xs text-slate-600" title="Sent before preview capture was added">
                          Not available
                        </span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {/* Rendered into document.body so the fixed overlay is anchored to the
          viewport — an ancestor with a CSS transform would otherwise make
          `position: fixed` relative to IT, dropping the modal far down the page. */}
      {preview &&
        preview.html &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4"
            onClick={() => setPreview(null)}
          >
          <div
            className="card flex h-[85vh] w-full max-w-2xl flex-col overflow-hidden p-0"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-start justify-between gap-4 border-b border-white/[0.06] px-5 py-3">
              <div className="min-w-0">
                <p className="truncate text-sm font-semibold text-white">
                  {preview.subject ?? "(no subject captured)"}
                </p>
                <p className="mt-0.5 truncate text-xs text-slate-500">
                  To {preview.toEmail} · {fmt(preview.sentAt)} · {preview.campaignName}
                </p>
              </div>
              <button onClick={() => setPreview(null)} className="btn-ghost text-xs">
                Close
              </button>
            </div>
            {preview.error && (
              <div className="border-b border-red-500/20 bg-red-500/10 px-5 py-2 text-xs text-red-300">
                {preview.error}
              </div>
            )}
            <iframe
              title="Sent email preview"
              srcDoc={stripTrackingPixel(preview.html)}
              sandbox=""
              className="w-full flex-1 border-0 bg-white"
            />
          </div>
          </div>,
          document.body,
        )}
    </>
  );
}

export default SentEmailViewer;

import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import { SentEmailViewer, type SentEmailRow } from "@/components/admin/coldemail/SentEmailViewer";

export const dynamic = "force-dynamic";

/**
 * "Sent email preview" — the cold-email counterpart of the platform Email Log
 * viewer (app/admin/logs/page.tsx → EmailLogViewer), built per explicit user
 * request to match that page's exact pattern. Global (all campaigns) by
 * default with a campaign filter so it doesn't become an unusable firehose;
 * pass ?campaignId= to scope to one campaign.
 *
 * Only ColdSend rows persist a preview (subjectSent/bodyHtmlSent, written by
 * worker/coldemail.ts at send time) going forward — sends made before this
 * feature shipped never had their rendered content stored and show up here
 * with an explanatory "Not available" instead of a Preview button.
 */
export default async function ColdEmailSentPage({
  searchParams,
}: {
  searchParams: Promise<{ campaignId?: string }>;
}) {
  await requireArea("platform");
  const sp = await searchParams;
  const campaignId = (sp.campaignId ?? "").trim();

  const [campaigns, sends] = await Promise.all([
    db.coldCampaign.findMany({ select: { id: true, name: true }, orderBy: { name: "asc" } }),
    db.coldSend.findMany({
      where: {
        status: "SENT",
        ...(campaignId ? { campaignId } : {}),
      },
      include: {
        contact: { select: { email: true } },
        campaign: { select: { name: true } },
      },
      orderBy: { sentAt: "desc" },
      take: 200,
    }),
  ]);

  const rows: SentEmailRow[] = sends.map((s) => ({
    id: s.id,
    toEmail: s.contact.email,
    campaignName: s.campaign.name,
    subject: s.subjectSent,
    status: s.status,
    error: s.error,
    html: s.bodyHtmlSent,
    sentAt: (s.sentAt ?? s.createdAt).toISOString(),
    openedAt: s.openedAt ? s.openedAt.toISOString() : null,
    openCount: s.openCount,
    clickedAt: s.clickedAt ? s.clickedAt.toISOString() : null,
    clickCount: s.clickCount,
  }));

  return (
    <div className="space-y-6">
      <PageHeader
        title="Sent emails"
        sub="Every cold-email message actually sent, previewed exactly as the recipient received it — sandboxed so a preview never counts as a real open."
      />
      <SentEmailViewer
        rows={rows}
        campaigns={campaigns}
        selectedCampaignId={campaignId}
        showCampaignColumn={!campaignId}
      />
    </div>
  );
}
